import "core-js/modules/web.dom.iterable";
import { libraryList } from "@/api/safeDanger/report";
import { categoryTree } from "@/api/safeDanger/hiddenCategory";
// import {getHiddenPCDict} from "@/util/hiddenDict";

export default {
  name: "anliTable",
  components: {},
  props: ['roomId', 'selectAnlis'],
  data: function data() {
    return {
      tableList: [],
      loading: false,
      tableHeight: undefined,
      // 查询参数
      queryParams: {},
      multipleSelection: [],
      hiddenSourceList: null,
      firstCategoryList: null,
      secondCategoryList: null
    };
  },
  watch: {
    'queryParams.hiddenCategory': function queryParamsHiddenCategory(newVal, oldVal) {
      this.$set(this.queryParams, 'hiddenType', undefined);
      if (newVal) {
        this.secondCategoryList = this.firstCategoryList.filter(function (el) {
          return el.id == newVal;
        })[0].hiddenCategoryVOList;
      }
    }
  },
  created: function created() {
    this.initData();
    this.getList();
  },
  mounted: function mounted() {
    var _this = this;
    this.$nextTick(function () {
      var windowHeight = _this.$refs.droot.clientHeight; //窗口高度
      _this.tableHeight = windowHeight - 150 + 'px';
    });
    this.getCurrentHeight();
  },
  methods: {
    getCurrentHeight: function getCurrentHeight() {},
    handleQuery: function handleQuery() {
      this.getList();
    },
    resetQuery: function resetQuery() {
      this.resetForm("queryForm");
      this.queryParams = {};
      this.handleQuery();
    },
    initData: function initData() {
      var _this2 = this;
      this.getDicts('hidden_source').then(function (response) {
        _this2.hiddenSourceList = response.data;
      });

      // 隐患分类(一级、二级、三级)
      categoryTree().then(function (response) {
        // 一级
        _this2.firstCategoryList = response.data;
      });
    },
    getList: function getList() {
      var _this3 = this;
      this.loading = true;
      libraryList(this.queryParams).then(function (response) {
        _this3.tableList = response.rows;
        _this3.$nextTick(function () {
          if (_this3.selectAnlis) {
            _this3.tableList.forEach(function (item1) {
              _this3.selectAnlis.forEach(function (item2) {
                if (item1.id == item2.id) {
                  _this3.$refs.table.toggleRowSelection(item1, true);
                }
              });
            });
          }
        });
      }).finally(function () {
        _this3.loading = false;
      });
    },
    handleSelectionChangeEvent: function handleSelectionChangeEvent(val) {
      this.multipleSelection = val;
    },
    handleSelectEvent: function handleSelectEvent(selection, row) {
      if (this.multipleSelection.length >= 5) {
        this.$refs.table.toggleRowSelection(row, false);
        this.$message.warning('最多只能选5个');
      }
    },
    handleSelectAllEvent: function handleSelectAllEvent(selection) {
      var _this4 = this;
      if (selection.length >= 5) {
        selection.splice(5, selection.length - 5);
        this.$refs.table.clearSelection();
        selection.forEach(function (row) {
          _this4.$refs.table.toggleRowSelection(row, true);
        });
        this.$message.warning('最多只能选5个');
      }
    },
    handleSelect: function handleSelect() {
      var list = JSON.parse(JSON.stringify(this.$refs.table.selection));
      list.forEach(function (item, index) {
        item.name = "\u6848\u4F8B".concat(index + 1);
      });
      this.$emit('select', list);
    },
    handleCancel: function handleCancel() {
      this.$emit('closeRoom');
    },
    handleClose: function handleClose() {
      this.hiddenDialogVisible = false;
      this.getList();
    },
    // 隐患分类选中
    changeHiddenCategory: function changeHiddenCategory(value) {
      if (value || value === 0) {
        var data;
        if (value == 0) {
          // 机房
          data = this.categoryList;
          data.forEach(function (el) {
            return el.dictLabel = el.category;
          });
        } else {
          data = this.supervisionList;
          data.forEach(function (el) {
            return el.dictLabel = el.supervision;
          });
        }
        this.hiddenCategoryList2 = data;
      } else {
        this.hiddenCategoryList2 = [];
      }
    },
    // 格式化数据
    formatHiddenSource: function formatHiddenSource(row) {
      return this.selectDictLabel(this.hiddenSourceList, row.hiddenSource);
    }
  }
};
